const config = $input.first().json;

const topicSystem = `Ты — SEO-редактор в гейминг-нише. Твоя задача — предложить свежие, актуальные темы для статей, основываясь на реальных новостях и тенденциях индустрии за последние недели. Используй веб-поиск, чтобы темы были действительно актуальными (обновления игр, релизы, события, патчи, турниры), а не абстрактными "вечнозелёными" формулировками.

Верни ТОЛЬКО JSON-массив без markdown-обёртки и без пояснений, строго в формате:
[{"topic": "конкретная тема статьи", "language": "${config.language}"}]

Темы должны быть:
- на языке ${config.language}
- конкретными, не абстрактными (не "лучшие игры 2026", а например "Почему патч 2.3 в Baldur's Gate 3 разозлил часть фанатов")
- пригодными для гейминг-блога с уклоном в линкбилдинг`;

const topicUserMessage = `Предложи ${config.topicsCount} актуальных тем для статей на языке ${config.language}.`;

return [{ json: { ...config, topicSystem, topicUserMessage } }];

const response = $input.first().json;
const messageItem = (response.output || []).find(o => o.type === 'message');
if (!messageItem) {
  throw new Error('OpenAI не вернул сообщение с темами. Проверь ответ API: ' + JSON.stringify(response).slice(0, 500));
}
const textPart = (messageItem.content || []).find(c => c.type === 'output_text');
if (!textPart) {
  throw new Error('Нет текстового content в сообщении OpenAI.');
}

let raw = textPart.text.trim();
raw = raw.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```$/,'').trim();

let topics;
try {
  topics = JSON.parse(raw);
} catch (e) {
  throw new Error('Не удалось распарсить JSON тем: ' + raw);
}

const config = $('Config').first().json;

return topics.map(t => ({
  json: {
    topic: t.topic,
    language: t.language || config.language,
    anchorText: config.anchorText,
    targetUrl: config.targetUrl
  }
}));

const response = $input.first().json;
const articleText = (response.choices?.[0]?.message?.content || '').trim();
const prev = $('Build Article Prompt').first().json;

const safeName = (prev.topic || 'article')
  .slice(0, 60)
  .replace(/[\\/:*?"<>|]+/g, '-')
  .replace(/\s+/g, ' ')
  .trim();
const fileName = `${safeName} [${prev.language}].txt`;

return [{
  json: {
    topic: prev.topic,
    language: prev.language,
    anchorText: prev.anchorText,
    targetUrl: prev.targetUrl,
    articleText,
    charCount: articleText.length,
    fileName
  }
}];
